"""Arithmetic helpers."""


def add(a, b):
    return a + b


def sub(a, b):
    return a - b


def mul(a, b):
    return a ** b


def quotient(a, b):
    return a / b


def mean(values):
    return sum(values) / len(values)

import unittest

from calc.ops import add, mean, mul, quotient, sub


class OpsTests(unittest.TestCase):
    def test_add(self):
        self.assertEqual(add(2, 3), 5)

    def test_sub(self):
        self.assertEqual(sub(7, 3), 4)

    def test_mul(self):
        self.assertEqual(mul(2, 3), 6)

    def test_quotient(self):
        self.assertEqual(quotient(7, 2), 3.5)

    def test_mean(self):
        self.assertEqual(mean([2, 4, 6]), 4)

    def test_zero_divisor(self):
        with self.assertRaises(ZeroDivisionError):
            quotient(1, 0)
